-- Fakt kartochkalari orqa tomonining ruscha matni — 60-partiya:
-- Asqad Muxtor, Atoyi, Avaz O'tar.

UPDATE fact_cards SET detail_ru = 'Аскад Мухтар родился 23 декабря 1920 года в городе Фергане. Он вырос в семье железнодорожного рабочего. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2114;
UPDATE fact_cards SET detail_ru = 'Роман «Сёстры» был издан в 1955 году и считается одним из важных романов Аскада Мухтара. Он упоминается в ряду его сочинений, осветивших важные вопросы своего времени. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2115;
UPDATE fact_cards SET detail_ru = 'Роман «Чинара» был издан в 1973 году. Писателю принадлежат также романы «Рождение» (1963) и «Время в моей судьбе» (1964). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2116;
UPDATE fact_cards SET detail_ru = 'Аскад Мухтар — автор стихотворных книг «Сталевар» (1947), «Мои земляки» (1949), «От чистого сердца» (1956). Известными его стихотворными сборниками считаются «99 миниатюр» и «Колокольчик каравана». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2117;
UPDATE fact_cards SET detail_ru = 'В 1960–1965 годах Аскад Мухтар был главным редактором журнала «Шарк юлдузи». Работал он редактором и в журнале «Гулистан», и в еженедельнике «Узбекистон адабиёти ва санъати». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2118;
UPDATE fact_cards SET detail_ru = 'Писатель переложил на узбекский язык сочинения Софокла, Тагора, Пушкина, Лермонтова, Маяковского, Горького, Шевченко и Блока. Своими переводами он донёс образцы мировой словесности до узбекских читателей. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2119;
UPDATE fact_cards SET detail_ru = 'Аскад Мухтар в 1972 году был награждён республиканской Государственной премией имени Хамзы. В 1980 году он получил звание народного писателя Узбекистана, а в 1995-м — орден «Дустлик». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2120;
UPDATE fact_cards SET detail_ru = 'Аскад Мухтар умер 17 апреля 1997 года в Ташкенте. Он оставил глубокий след в узбекской словесности как писатель, поэт и переводчик. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2121;

UPDATE fact_cards SET detail_ru = 'Точный год рождения Атаи неизвестен; это поэт, живший в XV веке. В источниках отмечается его связь с Балхом. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2122;
UPDATE fact_cards SET detail_ru = 'Алишер Навои в сочинении «Маджолис ун-нафоис» написал, что Атаи был из детей Исмаила-ота. А в сочинении «Насоим уль-мухаббат» Навои говорит, что Исмаил-ота был сыном Ибрагима-ота, младшего брата Ахмада Яссави. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2123;
UPDATE fact_cards SET detail_ru = 'Атаи жил в Самарканде, Бухаре и Балхе и глубоко изучил тюркскую, персидскую и арабскую словесность. Творил он на тюркском и персидском языках. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2124;
UPDATE fact_cards SET detail_ru = 'В источнике эти сведения даются с осторожностью: «По сообщению Навои, Атаи бывал и среди поэтов двора Улугбека». То есть это известие опирается на сведения Алишера Навои; других подробностей о придворной жизни поэта в источнике не приводится. Пора Улугбека была в Самарканде временем расцвета науки и словесности. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2125;
UPDATE fact_cards SET detail_ru = 'Атаи творил в основном в жанре газели и пользовался размером рамаль из аруза. Его стихи легки по напеву, строки коротки, а язык прост, потому они обращались в народные песни; в них часто встречаются народные обороты, пословицы и поговорки. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2126;
UPDATE fact_cards SET detail_ru = 'Рукописный список дивана Атаи, переписанный примерно в XVI веке, хранится в Санкт-Петербурге. На переплёте и в конце рукописи отмечено «Диван Шейхзаде Атаи», и в нём собрано 260 газелей. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2127;
UPDATE fact_cards SET detail_ru = 'Алишер Навои в сочинении «Маджолис ун-нафоис» описал Атаи как человека «дервишеского вида и доброго нрава» и отметил, что стихи его в своё время были широко известны среди тюрок. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2128;
UPDATE fact_cards SET detail_ru = 'Год смерти Атаи в источниках не отмечен; он жил в XV веке. Рукописный список его дивана, переписанный примерно в XVI веке, дошёл до нас и хранится в Санкт-Петербурге. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2129;

UPDATE fact_cards SET detail_ru = 'Аваз Отар родился 15 августа 1884 года в Хиве. Его отец был известен под именем Полванияз Отар. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2028;
UPDATE fact_cards SET detail_ru = 'Он учился сперва в школе, затем в хивинском медресе Инакия. В восемнадцать лет он был известен в народе как поэт. Источник: Ziyouz.com.' WHERE id = 2029;
UPDATE fact_cards SET detail_ru = 'Хивинский хан Мухаммад Рахим Второй (Феруз), оценив дарование молодого поэта, позвал его ко двору и назначил ему наставником Табиби. Однако Аваз не смог свыкнуться с придворной жизнью и покинул двор. Источник: Ziyouz.com.' WHERE id = 2030;
UPDATE fact_cards SET detail_ru = 'От Аваза Отара сохранились диваны «Саодат уль-икбол» и «Девони Аваз». Рукописные списки хранятся в Институте востоковедения Академии наук Узбекистана. Источник: Ziyouz.com.' WHERE id = 2031;
UPDATE fact_cards SET detail_ru = 'В начале XX века в его творчестве главное место заняли мысли о свободе, вольности и просвещении. К ним относятся стихи «Нация», «Свобода», «Найдётся ли когда-нибудь», «Народ», «Время». Источник: Ziyouz.com.' WHERE id = 2032;
UPDATE fact_cards SET detail_ru = 'В стихотворении «Школа» поэт мечтал о том, чтобы школа сделала нацию благоустроенной, а молодёжь училась и набиралась знаний. Это стихотворение — яркий образец его просветительских взглядов. Источник: Ziyouz.com.' WHERE id = 2033;
UPDATE fact_cards SET detail_ru = 'У него был цикл сатирических стихов под названием «Некто». Его стихи печатались и в журналах «Ойина», «Вакт», «Мулла Насриддин». Источник: Ziyouz.com.' WHERE id = 2034;
UPDATE fact_cards SET detail_ru = 'Аваз Отар умер в 1919 году в Хиве. Позже его имя было присвоено школам, улицам и скверам республики, а в Хиве устроен его дом-музей и поставлен памятник. Источник: Ziyouz.com.' WHERE id = 2035;
